"""Writes dev/fixtures.js: the real example CSV plus cases chosen to break the chart."""
import csv, json, pathlib, random
ROOT = pathlib.Path(__file__).resolve().parent.parent
rows = list(csv.DictReader(open(ROOT / 'example' / 'countries-population-life-expectancy-2021.csv', encoding='utf-8')))
COLS = ['Country', 'Region', 'Income group', 'Population', 'Life expectancy']
real = [{'Country': r['Country'], 'Region': r['Region'], 'Income group': r['Income group'], 'Population': float(r['Population']), 'Life expectancy': float(r['Life expectancy'])} for r in rows]
ENC = {'item': 'Country', 'cluster': 'Region', 'size': 'Population', 'color': 'Income group'}
F = {}
F['countries'] = {'label': 'Countries by region, sized by population (World Bank)', 'columns': COLS, 'rows': real, 'enc': ENC}
F['nocolor'] = {'label': 'Same, no Colour shelf', 'columns': COLS, 'rows': real, 'enc': {'item': 'Country', 'cluster': 'Region', 'size': 'Population'}}
F['lifeexp'] = {'label': 'Sized by life expectancy', 'columns': COLS, 'rows': real, 'enc': {'item': 'Country', 'cluster': 'Income group', 'size': 'Life expectancy', 'color': 'Region'}}
F['one'] = {'label': 'One cluster', 'columns': COLS, 'rows': [r for r in real if r['Region'] == 'North America'], 'enc': ENC}
F['single'] = {'label': 'A single row', 'columns': ['A', 'B', 'V'], 'rows': [{'A': 'Only item', 'B': 'Only cluster', 'V': 42.0}], 'enc': {'item': 'A', 'cluster': 'B', 'size': 'V'}}
F['bad'] = {'label': 'Zeroes, negatives, blanks, ties, duplicates', 'columns': ['A', 'B', 'V'], 'rows': [
    {'A': 'zero', 'B': 'g1', 'V': 0.0}, {'A': 'negative', 'B': 'g1', 'V': -5.0}, {'A': 'ok', 'B': 'g1', 'V': 10.0},
    {'A': None, 'B': 'g2', 'V': 10.0}, {'A': 'no cluster', 'B': None, 'V': 10.0}, {'A': 'dup', 'B': 'g2', 'V': 10.0}, {'A': 'dup', 'B': 'g2', 'V': 10.0},
    {'A': 'tie 1', 'B': 'g3', 'V': 7.0}, {'A': 'tie 2', 'B': 'g3', 'V': 7.0}, {'A': 'tie 3', 'B': 'g3', 'V': 7.0}], 'enc': {'item': 'A', 'cluster': 'B', 'size': 'V'}}
LONG = 'An extraordinarily long cluster name that keeps going and going and going'
F['long'] = {'label': 'Very long names', 'columns': ['A', 'B', 'V'], 'rows': [
    {'A': 'An item with a name that is also much too long to fit inside any circle at all', 'B': LONG, 'V': 900.0},
    {'A': 'Short', 'B': LONG, 'V': 300.0}, {'A': 'Wee', 'B': 'Tiny', 'V': 5.0}, {'A': 'Medium', 'B': 'Medium sized cluster', 'V': 120.0}], 'enc': {'item': 'A', 'cluster': 'B', 'size': 'V'}}
random.seed(11)
def big(n):
    return [{'A': 'Item %d' % i, 'B': 'Cluster %d' % (i % 9), 'C': 'Kind %d' % (i % 5), 'V': float(round(random.paretovariate(1.3) * 10, 2))} for i in range(n)]
F['big'] = {'label': 'Stress: 1,200 circles', 'columns': ['A', 'B', 'C', 'V'], 'rows': big(1200), 'enc': {'item': 'A', 'cluster': 'B', 'size': 'V', 'color': 'C'}}
F['huge'] = {'label': 'Stress: 2,000 circles (no per-circle animation)', 'columns': ['A', 'B', 'C', 'V'], 'rows': big(2000), 'enc': {'item': 'A', 'cluster': 'B', 'size': 'V', 'color': 'C'}}
F['empty'] = {'label': 'No rows', 'columns': ['A', 'B', 'V'], 'rows': [], 'enc': {'item': 'A', 'cluster': 'B', 'size': 'V'}}
F['noenc'] = {'label': 'Shelves empty (inferred)', 'columns': COLS, 'rows': real[:60], 'enc': {}}
(ROOT / 'dev' / 'fixtures.js').write_text('/* Generated by tools/make_fixtures.py. Do not edit. */\nwindow.SC_FIXTURES = ' + json.dumps(F, separators=(',', ':')) + ';\n', encoding='utf-8')
print('fixtures', {k: len(v['rows']) for k, v in F.items()})
